/**
 * 积分系统API客户端
 */
import { api } from '@/scripts/api'

export interface PointsBalance {
  userId: string
  balance: number
  status: string
  createTime: string | null
  updateTime: string | null
}

export interface ValidatePointsResult {
  allowed: boolean
  balance: number
}

export interface DeductPointsResult {
  userId: string
  deductedPoints: number
  balance: number
}

export interface RechargeOrder {
  orderId: string
  amount: number
  points: number
  paymentMethod: string
  paymentUrl: string
  status: string
  createTime: string | null
}

export interface PointsStats {
  balance: number
  totalEarned: number
  totalConsumed: number
}

export interface PointsTransaction {
  id: number
  transactionType: 'init' | 'recharge' | 'deduct'
  amount: number
  balanceBefore: number
  balanceAfter: number
  remark: string | null
  createTime: string
}

export type FilterType = 'all' | 'earned' | 'consumed'

export interface GetTransactionsParams {
  page?: number
  pageSize?: number
  type?: FilterType
}

export interface GetTransactionsResponse {
  transactions: PointsTransaction[]
  page: number
  pageSize: number
  total: number
  totalPages: number
}

export interface ClaimDailyPointsResult {
  amount: number
  balance: number
}

export class PointsApi {
  async getBalance(): Promise<PointsBalance> {
    const res = await api.fetchApi('/points/accounts/balance')
    if (res.status !== 200) {
      throw new Error(`Failed to get balance: ${res.status}`)
    }
    return await res.json()
  }

  async validatePoints(userId: string): Promise<ValidatePointsResult> {
    const res = await api.fetchApi('/points/accounts/validate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId })
    })
    if (res.status !== 200) {
      throw new Error(`Failed to validate points: ${res.status}`)
    }
    return await res.json()
  }

  async deductPoints(userId: string, duration: number): Promise<DeductPointsResult> {
    const res = await api.fetchApi('/points/accounts/deduct', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId, duration })
    })
    if (res.status !== 200) {
      throw new Error(`Failed to deduct points: ${res.status}`)
    }
    return await res.json()
  }

  async createRechargeOrder(
    userId: string,
    amount: number,
    paymentMethod: 'alipay' | 'wechat'
  ): Promise<RechargeOrder> {
    const res = await api.fetchApi('/points/recharge/orders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId, amount, paymentMethod })
    })
    if (res.status !== 200) {
      throw new Error(`Failed to create recharge order: ${res.status}`)
    }
    return await res.json()
  }

  async getStats(): Promise<PointsStats> {
    const res = await api.fetchApi('/points/accounts/stats')
    if (res.status !== 200) {
      throw new Error(`Failed to get stats: ${res.status}`)
    }
    return await res.json()
  }

  async getTransactions(params: GetTransactionsParams = {}): Promise<GetTransactionsResponse> {
    const query = new URLSearchParams({
      page: String(params.page ?? 1),
      pageSize: String(params.pageSize ?? 10),
      type: params.type ?? 'all'
    })
    const res = await api.fetchApi(`/points/transactions?${query}`)
    if (res.status !== 200) {
      throw new Error(`Failed to get transactions: ${res.status}`)
    }
    return await res.json()
  }

  async claimDailyPoints(): Promise<ClaimDailyPointsResult> {
    const res = await api.fetchApi('/points/accounts/claim-daily', {
      method: 'POST'
    })
    if (res.status !== 200) {
      const data = await res.json().catch(() => ({}))
      throw new Error(data.error || data.message || `Failed to claim daily points: ${res.status}`)
    }
    return await res.json()
  }
}

export const pointsApi = new PointsApi()
